	// keep discards temp in favour of final, which is already there. As
	// Git's finalize_object_file checks for a collision[1], a final that
	// is not writable must hold what temp holds: a final file whose
	// contents differ, such as a truncated index left by a failed save,
	// fails the save rather than being kept.
	keep := func(temp, final string, writable bool) error {
		if !writable && !checked[final] {
			same, err := sameContents(w.fs, temp, final)
			if err != nil {
				return err
			}
			if !same {
				return fmt.Errorf("files %q and %q differ in contents", temp, final)
			}
		}
		discard(temp)
		return nil
	}

	// place renames temp to final and records that it is no longer this
	// writer's to remove, or keeps final when it is already there,
	// including when another writer placed it between the check and the
	// rename. On Windows a rename over a read-only file fails, and placed
	// files are made read-only, so that shows up as a failed rename. A
	// placed file is made read-only unless writable is set.
	place := func(temp, final string, writable bool) error {
		if temp == "" {
			return nil
		}
		exists, err := fileExists(w.fs, final)
		if err != nil {
			return err
		}
		if exists {
			return keep(temp, final, writable)
		}
		if err := w.fs.Rename(temp, final); err != nil {
			if exists, _ := fileExists(w.fs, final); exists {
				return keep(temp, final, writable)
			}
			return err
		}
		delete(temps, temp)
		if !writable {
			fixPermissions(w.fs, final)
		}
		return nil
	}

	// stage writes a temporary file for final, even when final exists, so
	// An identical pack already on disk is left exactly as it is, marked or
	// not. Packs are content addressed, so the same hash means the same
	// objects, and nothing is missing that was not missing before; marking it
	// now would newly declare the repository a partial clone on the strength
	// of a duplicate. Only a pack the check above found in place counts: one
	// that went away during it is placed anew, so it gets its marker.
	if w.promisor != nil && !checked[packPath] {
		promisorPath := base + promisorExt
		promisorTemp, err := stage("tmp_promisor_", func(f io.Writer) error {
			_, err := io.WriteString(f, *w.promisor)
			return err
		})
		if err != nil {
			return err
		}
		// The marker keeps the 0600 its temporary file was created with, as
		// index-pack --promisor creates it[1]. fetch-pack rewrites an
		// existing marker in place[2], which a read-only one would refuse.
		//
		// [1]: https://github.com/git/git/blob/v2.54.0/builtin/index-pack.c#L1557-L1587
		// [2]: https://github.com/git/git/blob/v2.54.0/pack-write.c#L601-L614
		if err := place(promisorTemp, promisorPath, true); err != nil {
			return err
		}
	}

	if err := place(w.fw.Name(), packPath, false); err != nil {
		return err
	}
	if err := place(revTemp, revPath, false); err != nil {
		return err
}

